    {
        "name": "Ammonia Poisoning",
        "name_ja": "アンモニア中毒",
        "symptoms": {"skin_redness", "hemorrhage", "gasping", "erratic_swimming", "lethargy", "sudden_death", "gill_abnormality"},
        "description": "Ammonia Poisoning is a toxicological condition caused by exposure to harmful substances.",
        "description_ja": "水中アンモニア濃度上昇による鰓・皮膚の障害。",
        "urgency": "emergency",
        "recommended_tests": ["水質検査（アンモニア）", "鰓検査", "血液検査"],
        "causes": "Caused by elevated ammonia levels in the aquatic environment due to inadequate filtration, overcrowding, or overfeeding. Ammonia damages gill epithelium and permeable skin.",

        "causes_ja": "両生類におけるアンモニア中毒の原因: 水中アンモニア濃度上昇による鰓・皮膚の障害。",
        "pathophysiology": "The pathological process involves tissue injury, inflammatory response, and progressive functional impairment. Without intervention, compensatory mechanisms may be overwhelmed, leading to clinical deterioration.",
        "pathophysiology_ja": "アンモニア中毒は両生類における中毒性疾患である。有害物質の経口摂取、吸入、または経皮吸収により中毒障害が生じる。毒素は酵素阻害、受容体干渉、酸化的損傷、直接的な細胞毒性などの特定のメカニズムを通じて細胞プロセスを障害する。標的臓器は毒素により異なるが、肝臓（生体内変換）、腎臓（排泄）、神経系、消化管が一般的である。用量依存的に無症候性変化から劇症型臓器不全まで幅広い影響を及ぼす。",
        "treatment": "Treatment includes decontamination (if recent ingestion), specific antidotes where available, supportive care, fluid therapy, and monitoring of organ function.",
        "treatment_ja": "両生類におけるアンモニア中毒の治療には迅速な除染と支持療法が必要である。摂取直後であれば催吐（種にとって安全な場合）または胃洗浄により吸収を低減する。活性炭は多くの毒素を吸着する。特異的解毒剤がある場合は投与する（例：抗凝固性殺鼠剤にビタミンK1、アセトアミノフェンにN-アセチルシステイン）。積極的な輸液療法で腎排泄を促進し灌流を維持する。臓器特異的障害（肝、腎、神経）をモニタリングし治療する。",
        "prevention": "Prevention includes removing access to toxic substances, using pet-safe products, proper storage of medications and chemicals, and educating owners about common toxins.",
        "prevention_ja": "アンモニア中毒の予防には有毒物質へのアクセス制限・除去、ペット安全な製品の使用、環境からの有毒植物の除去、薬剤・化学物質の適切な保管、屋外アクセス時の監視、種固有の中毒に関する飼い主教育が必要である。",
        "prognosis": "Prognosis depends on the toxin, amount ingested, and time to treatment. Early decontamination and aggressive supportive care improve outcomes. Severe organ damage may be irreversible.",
        "prognosis_ja": "アンモニア中毒の予後: 治療開始時間による。",
        "onset_pattern": {"acute"},
        "age_predisposition": {"young", "adult", "senior"},
    },
