    {
        "name": "Spring Disease (Post-hibernation Syndrome)",
        "name_ja": "春病（冬眠後症候群）",
        "symptoms": {"lethargy", "anorexia", "edema", "red_legs", "hemorrhage", "weakness"},
        "description": "Spring Disease (Post-hibernation Syndrome) is a clinical condition requiring veterinary evaluation, diagnosis, and appropriate treatment.",
        "description_ja": "冬眠後の免疫抑制に伴う細菌性敗血症。野生捕獲個体に多い。",
        "urgency": "high",
        "recommended_tests": ["血液検査", "細菌培養", "身体検査"],
        "causes": "Post-hibernation immunosuppression leading to bacterial septicemia; common in wild-caught specimens.",
        "causes_ja": "両生類における春病（冬眠後症候群）の原因: 冬眠後の免疫抑制に伴う細菌性敗血症。野生捕獲個体に多い。",
        "pathophysiology": "Post-hibernation immunosuppression leading to bacterial septicemia; common in wild-caught specimens. Pathogenic bacteria colonize tissues through adhesion factors and invade via virulence mechanisms including toxin production, enzyme secretion, and immune evasion strategies. The resulting inflammatory cascade involves neutrophil infiltration, cytokine release, and complement activation. Tissue damage results from both direct bacterial action and the host's inflammatory response. Abscess formation, septicemia, or chronic granulomatous inflammation may develop depending on the organism and host immune status.",
        "pathophysiology_ja": "春病（冬眠後症候群）は両生類における細菌感染症である。病原菌は付着因子を通じて組織にコロニーを形成し、毒素産生、酵素分泌、免疫回避戦略などの病原性メカニズムを介して侵入する。好中球浸潤、サイトカイン放出、補体活性化を含む炎症カスケードが生じる。組織損傷は細菌の直接作用と宿主の炎症反応の両方に起因する。菌種と宿主の免疫状態に応じて、膿瘍形成、敗血症、または慢性肉芽腫性炎症が発生しうる。",
        "treatment": "Appropriate medical or surgical intervention based on diagnosis, supportive care with IV fluids as needed, pain management, nutritional support, and regular monitoring of treatment response.",
        "treatment_ja": "両生類における春病（冬眠後症候群）の治療には、可能であれば培養感受性試験に基づく標的抗菌薬療法が必要である。結果待ちの間は経験的広域抗菌薬を開始する。抗菌薬治療期間は感染の排除と耐性予防に十分な期間とする。膿瘍や壊死組織には外科的排膿またはデブリードマンが必要な場合がある。支持療法として輸液、鎮痛薬、抗炎症薬、栄養サポートを行う。",
        "prevention": "Prevention includes appropriate husbandry, balanced nutrition, regular veterinary examinations, stress reduction, and prompt treatment of early signs of illness.",
        "prevention_ja": "春病（冬眠後症候群）の予防には適切な衛生管理・消毒、利用可能なワクチン接種、創傷の迅速な処置、ストレス軽減、適切な換気、感染動物の隔離が含まれる。",
        "prognosis": "Prognosis depends on disease severity, timeliness of intervention, and response to treatment. Early diagnosis and appropriate therapy generally improve outcomes.",
        "prognosis_ja": "春病（冬眠後症候群）の予後: 早期治療で多くは良好。定期モニタリングで管理可能。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"young", "adult", "senior"},
    },
