    {
        "name": "Perkinsea Infection",
        "name_ja": "パーキンシア感染症",
        "symptoms": {"internal_hemorrhage", "lethargy", "liver_enlargement", "sudden_death"},
        "description": "Perkinsea Infection is a bacterial infection that causes systemic or localized inflammatory disease requiring prompt antimicrobial therapy.",
        "description_ja": "幼生および成体の両生類に大量死を引き起こす原生生物寄生虫。",
        "urgency": "emergency",
        "recommended_tests": ["histopathology", "PCR_perkinsea", "liver_biopsy"],
        "causes": "Protist parasite causing mass mortality events in larval and adult amphibians.",
        "causes_ja": "両生類におけるパーキンシア感染症の原因: 幼生および成体の両生類に大量死を引き起こす原生生物寄生虫。",
        "pathophysiology": "Perkinsea Infection is a parasitic condition. Protist parasite causing mass mortality events in larval and adult amphibians. The parasite establishes infection through ingestion, percutaneous penetration, or vector-mediated transmission. It exploits host resources for nutrition and reproduction while evading immune defenses through antigenic variation, immunomodulation, or intracellular sequestration. Tissue damage results from direct parasitic feeding, mechanical disruption, toxic metabolic byproducts, and the host's inflammatory and immune responses. Heavy parasite burdens can lead to anemia, malnutrition, organ dysfunction, and secondary infections.",
        "pathophysiology_ja": "パーキンシア感染症は両生類における寄生虫疾患である。寄生虫は経口摂取、経皮的侵入、またはベクター媒介伝播を通じて感染を確立する。抗原変異、免疫調節、細胞内隔離により宿主の免疫防御を回避しながら、宿主の栄養と資源を利用して増殖する。組織損傷は寄生虫の直接的な摂食、機械的破壊、有毒代謝副産物、宿主の炎症・免疫応答に起因する。重度の寄生虫感染は貧血、栄養失調、臓器機能障害、二次感染を引き起こしうる。",
        "treatment": "Treatment of perkinsea infection in amphibian requires appropriate antiparasitic medication selected based on the specific parasite identified. Species-appropriate dosing is critical as some antiparasitics are toxic to certain species. Treatment may require multiple doses to eliminate all life stages. Environmental decontamination and in-contact animal treatment prevent reinfection. Supportive care addresses secondary complications such as anemia, dehydration, or malnutrition.",
        "treatment_ja": "両生類におけるパーキンシア感染症の治療には、同定された寄生虫に応じた適切な駆虫薬が必要である。一部の駆虫薬は特定の種に有毒であるため、種に適した用量設定が重要である。全てのライフステージを排除するため複数回投与が必要な場合がある。環境消毒と接触動物の治療で再感染を防止する。貧血、脱水、栄養失調などの二次的合併症に対する支持療法を行う。",
        "prevention": "Prevention includes maintaining proper hygiene, appropriate husbandry, stress reduction, quarantine of new animals, and prompt treatment of wounds or primary conditions.",
        "prevention_ja": "パーキンシア感染症の予防には定期的な予防駆虫、環境衛生と糞便除去、新規動物の隔離・検査、ベクター防除、中間宿主や汚染環境への曝露回避が含まれる。",
        "prognosis": "Prognosis depends on severity, underlying cause, and timeliness of treatment. Early aggressive intervention generally improves outcomes. Delayed presentation carries a guarded to poor prognosis.",
        "prognosis_ja": "パーキンシア感染症の予後: 早期治療で多くは良好。定期モニタリングで管理可能。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"young", "adult", "senior"},
    },
