    # ══════════════════════════════════════════════════════════════════
    # 新規追加: 大型サンショウウオ (Giant Salamander) 関連疾患
    # Andrias davidianus / A. japonicus / A. sligoi — 世界最大の両生類
    # ══════════════════════════════════════════════════════════════════
    {
        "name": "Giant Salamander Skin Ulcer Disease",
        "name_ja": "オオサンショウウオ皮膚潰瘍病",
        "symptoms": {"skin_ulcers", "skin_lesions", "hemorrhage", "lethargy", "anorexia", "skin_redness", "excessive_mucus", "weight_loss"},
        "description": "Severe ulcerative dermatitis in giant salamanders (Andrias spp.) caused by Aeromonas hydrophila and other gram-negative bacteria, often secondary to stress or water quality deterioration.",
        "description_ja": "オオサンショウウオ（Andrias属）に多発する重度の潰瘍性皮膚炎。Aeromonas hydrophilaなどのグラム陰性菌による日和見感染で、ストレスや水質悪化が誘因。",
        "urgency": "high",
        "recommended_tests": ["細菌培養・感受性試験", "皮膚スワブ", "血液検査", "水質検査"],
        "causes": "Caused by opportunistic gram-negative bacteria (Aeromonas hydrophila, Pseudomonas spp.) that invade through skin abrasions. Predisposing factors include poor water quality, overcrowding in captive breeding facilities, elevated water temperature above 20°C, and handling stress.",
        "causes_ja": "Aeromonas hydrophila等のグラム陰性菌が皮膚損傷部位から侵入。水質悪化（アンモニア・亜硝酸上昇）、過密飼育、20°C以上の水温上昇、ハンドリングストレスが素因。",
        "pathophysiology": "Bacteria colonize damaged skin through adhesion factors, producing cytotoxic exotoxins (aerolysin, hemolysin) that cause tissue necrosis. The inflammatory cascade leads to ulceration, secondary septicemia, and potentially fatal organ failure in severe cases.",
        "pathophysiology_ja": "細菌が損傷皮膚に定着し、エアロリジン・ヘモリジン等の細胞毒性外毒素を産生して組織壊死を誘導。炎症カスケードにより潰瘍が拡大し、重症例では二次的敗血症から多臓器不全に至る。",
        "treatment": "Enrofloxacin (5-10 mg/kg IM or SC q24h for 14-21 days) or gentamicin (2.5 mg/kg IM q72h) based on culture sensitivity. Topical wound management with dilute povidone-iodine (0.5%) or silver sulfadiazine. Maintain water temperature at 15-18°C. Supportive care with electrolyte baths.",
        "treatment_ja": "培養感受性試験に基づく抗菌薬投与：エンロフロキサシン（5-10 mg/kg IM/SC 1日1回 14-21日間）またはゲンタマイシン（2.5 mg/kg IM 72時間毎）。創部は希釈ポビドンヨード（0.5%）または銀スルファジアジンで局所処置。水温15-18°Cを維持。電解質浴による支持療法。",
        "prevention": "Maintain excellent water quality (ammonia <0.02 mg/L, temperature 12-18°C). Avoid overcrowding. Minimize handling. Quarantine new animals for 30 days. Regular water changes (30% weekly).",
        "prevention_ja": "水質管理の徹底（アンモニア<0.02 mg/L、水温12-18°C）。過密飼育の回避。ハンドリングの最小化。新規個体の30日間検疫。週1回30%の換水。",
        "prognosis": "Fair to good with early treatment and culture-directed therapy. Poor prognosis if septicemia develops. Mortality can exceed 50% in captive breeding facility outbreaks.",
        "prognosis_ja": "早期治療と感受性試験に基づく治療で予後はやや良好。敗血症併発時は予後不良。飼育施設での集団発生時の致死率は50%を超えることがある。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"young", "adult", "senior"},
    },
    {
        "name": "Giant Salamander Iridovirus Disease",
        "name_ja": "オオサンショウウオイリドウイルス病",
        "symptoms": {"hemorrhage", "skin_hemorrhage", "petechiae", "edema", "lethargy", "anorexia", "sudden_death", "organ_failure"},
        "description": "A highly lethal iridoviral infection in Chinese and Japanese giant salamanders (Andrias spp.) causing systemic hemorrhagic disease with high mortality in farmed populations.",
        "description_ja": "中国産・日本産オオサンショウウオに発生する高致死性イリドウイルス感染症。養殖個体群で全身性出血性疾患を引き起こし、高い致死率を示す。",
        "urgency": "emergency",
        "recommended_tests": ["PCR検査", "ウイルス分離", "組織病理検査", "電子顕微鏡検査"],
        "causes": "Caused by Chinese giant salamander iridovirus (CGSIV), a ranavirus in the family Iridoviridae. Transmission occurs through direct contact, contaminated water, and fomites. Stress from overcrowding, poor water quality, and temperature fluctuations increases susceptibility.",
        "causes_ja": "イリドウイルス科ラナウイルス属のオオサンショウウオイリドウイルス（CGSIV）が原因。直接接触、汚染水、媒介物を介して伝播。過密飼育、水質悪化、水温変動によるストレスが感受性を増大。",
        "pathophysiology": "Virus replicates in endothelial cells and hematopoietic tissues, causing widespread hemorrhage, necrosis of liver, spleen, and kidney. Severe viremia leads to disseminated intravascular coagulation (DIC) and multi-organ failure.",
        "pathophysiology_ja": "ウイルスは血管内皮細胞と造血組織で増殖し、肝臓・脾臓・腎臓の広範な出血と壊死を引き起こす。重度のウイルス血症はDIC（播種性血管内凝固）と多臓器不全に至る。",
        "treatment": "No specific antiviral therapy available. Supportive care includes maintaining optimal water temperature (15-18°C), electrolyte supplementation, and treatment of secondary bacterial infections with broad-spectrum antibiotics. Isolation of affected animals is critical.",
        "treatment_ja": "特異的抗ウイルス薬は存在しない。支持療法として最適水温維持（15-18°C）、電解質補給、二次的細菌感染に対する広域抗菌薬投与。罹患個体の隔離が不可欠。",
        "prevention": "Strict biosecurity in breeding facilities. PCR screening of broodstock. Quarantine of new animals for 60 days. Disinfection with 10% bleach or chlorhexidine (0.75%). Avoid mixing wild-caught and captive animals.",
        "prevention_ja": "養殖施設での厳格なバイオセキュリティ。種親のPCRスクリーニング。新規個体の60日間検疫。10%次亜塩素酸ナトリウムまたはクロルヘキシジン（0.75%）による消毒。野生個体と飼育個体の混合回避。",
        "prognosis": "Poor. Mortality rates can reach 90-100% in naive populations. Survivors may become chronic carriers. No vaccine currently available.",
        "prognosis_ja": "予後不良。未感染集団での致死率は90-100%に達しうる。生存個体は慢性キャリアとなる可能性がある。現在ワクチンは利用不可。",
        "onset_pattern": {"acute"},
        "age_predisposition": {"puppy", "young", "adult"},
    },
    {
        "name": "Cryptobranchid Gill Disease (Larval)",
        "name_ja": "サンショウウオ科幼生鰓疾患",
        "symptoms": {"gill_necrosis", "gill_damage", "gill_abnormality", "rapid_breathing", "lethargy", "anorexia", "failure_to_thrive"},
        "description": "Gill disease affecting larval giant salamanders and hellbenders (Cryptobranchidae), caused by bacterial or fungal pathogens in suboptimal water conditions.",
        "description_ja": "オオサンショウウオ科（Cryptobranchidae）の幼生に発生する鰓疾患。不適切な水質環境における細菌・真菌感染が原因。",
        "urgency": "high",
        "recommended_tests": ["鰓生検", "細菌培養", "水質検査", "顕微鏡検査"],
        "causes": "Bacterial (Flavobacterium, Aeromonas) or fungal (Saprolegnia) infection of larval gills, precipitated by poor water quality, elevated ammonia/nitrite, low dissolved oxygen, or elevated temperature.",
        "causes_ja": "不良水質（アンモニア・亜硝酸上昇、溶存酸素低下、高水温）を背景としたFlavobacterium属、Aeromonas属細菌またはSaprolegnia属真菌による幼生鰓の感染。",
        "pathophysiology": "Pathogens colonize delicate gill filaments, causing inflammation, epithelial hyperplasia, and necrosis. Gas exchange impairment leads to hypoxia. Secondary systemic infection may develop.",
        "pathophysiology_ja": "病原体が繊細な鰓糸に定着し、炎症・上皮過形成・壊死を引き起こす。ガス交換障害により低酸素症に至る。二次的全身感染に発展しうる。",
        "treatment": "Improve water quality immediately. For bacterial gill disease: oxytetracycline bath (50 mg/L for 1 hour daily for 5 days). For fungal gill disease: methylene blue bath (2 mg/L for 30 min) or salt bath (5 g/L for 15 min). Increase aeration.",
        "treatment_ja": "直ちに水質改善。細菌性鰓疾患：オキシテトラサイクリン浴（50 mg/L 1時間/日 5日間）。真菌性鰓疾患：メチレンブルー浴（2 mg/L 30分）または食塩浴（5 g/L 15分）。エアレーション強化。",
        "prevention": "Maintain pristine water quality for larvae. Temperature 12-16°C for Cryptobranchidae larvae. Ammonia and nitrite at 0 ppm. Weekly water changes of 30-50%. Avoid overcrowding larvae.",
        "prevention_ja": "幼生用の清浄な水質維持。サンショウウオ科幼生の水温12-16°C。アンモニア・亜硝酸を0 ppmに。30-50%の週次換水。幼生の過密回避。",
        "prognosis": "Good if caught early and water quality is corrected. Poor prognosis if gill necrosis is extensive.",
        "prognosis_ja": "早期発見と水質改善で予後良好。鰓壊死が広範な場合は予後不良。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"puppy"},
    },

    # ══════════════════════════════════════════════════════════════════
    # 新規追加: ゴライアスガエル (Goliath Frog) 関連疾患
    # Conraua goliath — 世界最大のカエル
    # ══════════════════════════════════════════════════════════════════
    {
        "name": "Goliath Frog Stress Syndrome",
        "name_ja": "ゴライアスガエルストレス症候群",
        "symptoms": {"anorexia", "lethargy", "skin_discoloration", "weight_loss", "excessive_mucus", "reluctance_to_move", "vocalization_loss"},
        "description": "Chronic maladaptation syndrome in captive goliath frogs (Conraua goliath) due to inability to replicate their specific habitat requirements of fast-flowing, oxygen-rich rivers.",
        "description_ja": "ゴライアスガエル（Conraua goliath）の飼育下で発生する慢性不適応症候群。急流・高酸素の自然環境を再現できないことによるストレス反応。",
        "urgency": "moderate",
        "recommended_tests": ["血液検査", "水質検査（溶存酸素・pH・水温）", "糞便検査", "体重モニタリング"],
        "causes": "Chronic stress from captive conditions that cannot replicate the fast-flowing, oxygen-rich (>8 mg/L), slightly acidic (pH 6.5-7.0) rivers at 19°C that goliath frogs require. Insufficient space (adults need >200L per individual), lack of current flow, and inappropriate diet contribute.",
        "causes_ja": "ゴライアスガエルに必要な急流・高溶存酸素（>8 mg/L）・弱酸性（pH 6.5-7.0）・水温19°Cの環境を再現できない飼育条件による慢性ストレス。不十分なスペース（成体は1個体あたり200L以上必要）、水流不足、不適切な給餌が寄与。",
        "pathophysiology": "Chronic elevation of corticosterone suppresses immune function and reproductive capacity. Prolonged stress leads to catabolism, muscle wasting, and increased susceptibility to opportunistic infections.",
        "pathophysiology_ja": "コルチコステロンの慢性的上昇が免疫機能と生殖能力を抑制。持続的ストレスは異化作用亢進、筋萎縮、日和見感染への感受性増大を招く。",
        "treatment": "Optimize husbandry: provide large enclosure with strong water current (powerhead or canister filter), maintain water temperature at 18-22°C, dissolved oxygen >8 mg/L, pH 6.5-7.0. Offer varied diet of earthworms, crickets, small fish. Minimize visual disturbance. Anxiolytic environmental enrichment.",
        "treatment_ja": "飼育環境の最適化：強い水流を備えた大型水槽（パワーヘッドまたはキャニスターフィルター使用）、水温18-22°C、溶存酸素>8 mg/L、pH 6.5-7.0を維持。ミミズ・コオロギ・小魚の多様な餌を提供。視覚的刺激を最小化。環境エンリッチメントの導入。",
        "prevention": "Research species-specific requirements before acquisition. Provide naturalistic enclosure with adequate space and water flow. This species has never been bred in captivity; discourage acquisition for inexperienced keepers.",
        "prevention_ja": "飼育前に種固有の要件を十分調査。十分なスペースと水流を備えた自然に近い飼育環境の提供。本種は飼育下繁殖の成功例がなく、経験の浅い飼育者による取得は推奨しない。",
        "prognosis": "Guarded. Captive goliath frogs typically survive longer than wild counterparts (up to 21 years) but often show chronic stress signs. Behavioral normalization is difficult to achieve.",
        "prognosis_ja": "予後は慎重。飼育下のゴライアスガエルは野生個体より長寿（最長21年）であるが、慢性ストレス徴候を示すことが多い。行動の正常化は困難。",
        "onset_pattern": {"chronic"},
        "age_predisposition": {"young", "adult", "senior"},
    },
    {
        "name": "Goliath Frog Filariasis",
        "name_ja": "ゴライアスガエルフィラリア症",
        "symptoms": {"lethargy", "weight_loss", "anemia", "microfilaria_visible", "edema", "skin_lesions"},
        "description": "Filarial nematode infection in goliath frogs, with microfilariae detected in peripheral blood. A distinct filarial species unique to Conraua goliath (PMC6541376).",
        "description_ja": "ゴライアスガエルに発生するフィラリア線虫感染。末梢血中にミクロフィラリアが検出される。Conraua goliathに固有のフィラリア種（PMC6541376）。",
        "urgency": "moderate",
        "recommended_tests": ["末梢血塗抹標本", "ミクロフィラリア検査（ノット法）", "血液検査（CBC）", "PCR検査"],
        "causes": "Infection by a novel filarial nematode species specific to Conraua goliath, transmitted by blood-feeding arthropod vectors. Wild-caught individuals are commonly infected; the parasite-host relationship is normally balanced in stable ecosystems.",
        "causes_ja": "Conraua goliathに固有の新規フィラリア線虫種による感染。吸血節足動物ベクターを介して伝播。野生捕獲個体では一般的に感染しており、安定した生態系では寄生虫-宿主関係は均衡を保つ。",
        "pathophysiology": "Adult worms reside in lymphatic vessels or body cavity, releasing microfilariae into circulation. Heavy burdens can cause lymphatic obstruction, anemia, and secondary immune-mediated pathology. Habitat disruption increases pathogenic effects.",
        "pathophysiology_ja": "成虫はリンパ管または体腔内に寄生し、ミクロフィラリアを血中に放出。高度寄生ではリンパ管閉塞、貧血、二次的免疫介在性病態を引き起こす。生息地の攪乱が病原性効果を増大させる。",
        "treatment": "Ivermectin (0.2 mg/kg SC or topical, single dose, repeat in 14 days) for microfilariae reduction. Monitor for adverse reactions. Supportive care with iron supplementation for anemia. Treatment in wild-caught frogs should consider whether parasite load is clinically significant.",
        "treatment_ja": "イベルメクチン（0.2 mg/kg SC または経皮、単回投与、14日後に再投与）によるミクロフィラリア駆除。副反応のモニタリング。貧血に対する鉄剤補給による支持療法。野生捕獲個体では寄生虫量が臨床的に有意か検討した上で治療判断。",
        "prevention": "Quarantine wild-caught frogs and screen blood for microfilariae. Control arthropod vectors in captive environment. Captive-bred individuals (if available) are preferred.",
        "prevention_ja": "野生捕獲個体の検疫と末梢血のミクロフィラリアスクリーニング。飼育環境での節足動物ベクターの管理。飼育下繁殖個体（入手可能な場合）を優先。",
        "prognosis": "Generally good in stable hosts with light to moderate burdens. Heavy infections or stressed individuals have guarded prognosis.",
        "prognosis_ja": "軽度〜中等度の寄生で安定した宿主では予後良好。高度感染やストレス下の個体では予後は慎重。",
        "onset_pattern": {"chronic"},
        "age_predisposition": {"adult", "senior"},
    },

    # ══════════════════════════════════════════════════════════════════
    # 新規追加: パックマンフロッグ (Ceratophrys) 関連疾患
    # ══════════════════════════════════════════════════════════════════
    {
        "name": "Pacman Frog Water Edema Syndrome",
        "name_ja": "パックマンフロッグ水浮腫症候群",
        "symptoms": {"edema", "bloating", "lymph_sac_edema", "generalized_swelling", "lethargy", "anorexia", "regurgitation", "ascites"},
        "description": "Severe subcutaneous and coelomic fluid accumulation in horned frogs (Ceratophrys spp.), commonly called 'balloon frog syndrome'. Often secondary to renal failure, hepatic disease, or septicemia.",
        "description_ja": "ツノガエル属（Ceratophrys）に多発する重度の皮下・体腔内液貯留。「バルーンフロッグ症候群」と呼ばれる。腎不全、肝疾患、敗血症に続発することが多い。",
        "urgency": "high",
        "recommended_tests": ["体腔穿刺・液性状分析", "血液検査（BUN・UA）", "細菌培養", "超音波検査", "X線検査"],
        "causes": "Multifactorial: bacterial septicemia (Aeromonas, Flavobacterium), chronic renal failure, hepatic lipidosis from obesity, hypovitaminosis A causing immunosuppression, or chronic poor water quality. Obesity is rampant in captive Ceratophrys due to overfeeding.",
        "causes_ja": "多因子性：細菌性敗血症（Aeromonas、Flavobacterium）、慢性腎不全、過食による肝リピドーシス、低ビタミンA症による免疫抑制、慢性的な水質不良。飼育下のツノガエルでは過食による肥満が蔓延。",
        "pathophysiology": "Fluid accumulation results from increased vascular permeability (septicemia), decreased oncotic pressure (hypoalbuminemia from hepatic/renal disease), or lymphatic dysfunction. In frogs, subcutaneous lymph sacs are prominent, and fluid preferentially accumulates in these spaces.",
        "pathophysiology_ja": "血管透過性亢進（敗血症）、膠質浸透圧低下（肝・腎疾患による低アルブミン血症）、またはリンパ機能不全により液貯留が発生。カエルでは皮下リンパ嚢が発達しており、優先的にこの空間に液が貯留する。",
        "treatment": "Coelomic fluid drainage via percutaneous aspiration under sterile technique. Furosemide (2-5 mg/kg IM or topical) for diuresis. Epsom salt bath (5 g/2L dechlorinated water for 15 min). Antibiotics if septicemia suspected: enrofloxacin (5 mg/kg SC q24h). Address underlying cause. Do NOT raise water temperature.",
        "treatment_ja": "無菌的手技による経皮的体腔液排液。フロセミド（2-5 mg/kg IM または経皮）による利尿。エプソムソルト浴（5 g/2L 脱塩素水 15分間）。敗血症疑い時：エンロフロキサシン（5 mg/kg SC 1日1回）。基礎疾患の治療。水温を上げてはならない。",
        "prevention": "Avoid overfeeding (adult Ceratophrys: feed every 7-10 days). Maintain clean substrate. Regular partial water changes. Supplement with vitamin A. Monitor body condition score.",
        "prevention_ja": "過食回避（成体ツノガエル：7-10日毎の給餌）。清潔な床材の維持。定期的な部分換水。ビタミンA補給。体格スコアのモニタリング。",
        "prognosis": "Guarded to poor. Bacterial septicemia-associated edema is often fatal without aggressive treatment. Diet-related edema has better prognosis if underlying obesity and organ damage are addressed early.",
        "prognosis_ja": "予後は慎重〜不良。細菌性敗血症関連の浮腫は積極的治療なしでは致死的。食事関連浮腫は肥満と臓器障害を早期に対処すれば予後改善。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"adult", "senior"},
    },
    {
        "name": "Pacman Frog Gastric Overload Syndrome",
        "name_ja": "パックマンフロッグ胃過負荷症候群",
        "symptoms": {"bloating", "regurgitation", "lethargy", "dyspnea", "anorexia", "reluctance_to_move"},
        "description": "Acute gastric overload from ingestion of oversized prey items or excessive feeding in horned frogs (Ceratophrys spp.). Can lead to respiratory compromise and death.",
        "description_ja": "ツノガエル属（Ceratophrys）における過大な餌の摂取または過食による急性胃過負荷。呼吸障害から死亡に至る可能性がある。",
        "urgency": "high",
        "recommended_tests": ["X線検査", "超音波検査", "身体検査", "腹部触診"],
        "causes": "Ingestion of prey items that are too large (e.g., adult mice for juvenile frogs), excessive feeding volume in a single session, or accidental ingestion of indigestible substrate material.",
        "causes_ja": "過大な餌の摂取（幼体への成体マウス給餌など）、1回の給餌での過剰量、または不消化な床材の誤飲。",
        "pathophysiology": "Gastric distension compresses lungs and coelomic organs, impairing ventilation. Undigested prey undergoes bacterial decomposition in the stomach, producing gas and toxins. Gastric necrosis and perforation may occur in severe cases.",
        "pathophysiology_ja": "胃拡張が肺と体腔内臓器を圧迫し、換気を障害。未消化の餌が胃内で細菌分解を受け、ガスと毒素を産生。重症例では胃壊死・穿孔が発生しうる。",
        "treatment": "Gastric lavage under anesthesia (MS-222, 1-2 g/L) if recent ingestion. Manual removal of prey with atraumatic forceps or endoscope. Metoclopramide (2 mg/kg SC) as prokinetic if partial digestion. Cool environment to slow metabolism. Antibiotics if gastric compromise suspected.",
        "treatment_ja": "摂取後早期であれば麻酔下（MS-222, 1-2 g/L）での胃洗浄。非外傷性鉗子またはエンドスコープによる餌の除去。部分消化の場合メトクロプラミド（2 mg/kg SC）を消化管運動促進薬として投与。代謝抑制のため低温環境。胃損傷疑い時は抗菌薬投与。",
        "prevention": "Feed appropriately sized prey (no wider than the frog's head). Adult Ceratophrys: feed every 7-10 days. Avoid feeding mice to juvenile frogs. Use fine sand or paper towel substrate to prevent accidental ingestion.",
        "prevention_ja": "適切なサイズの餌を給与（カエルの頭部幅を超えない）。成体ツノガエル：7-10日毎の給餌。幼体へのマウス給餌回避。誤飲防止のため細砂またはペーパータオル床材を使用。",
        "prognosis": "Fair to good if treated promptly. Poor if gastric necrosis or perforation develops. Prevention through appropriate feeding is key.",
        "prognosis_ja": "迅速な治療で予後はやや良好。胃壊死・穿孔発生時は予後不良。適切な給餌による予防が重要。",
        "onset_pattern": {"acute"},
        "age_predisposition": {"puppy", "young", "adult"},
    },
    {
        "name": "Pacman Frog Substrate Impaction (Ceratophrys)",
        "name_ja": "パックマンフロッグ床材誤飲性閉塞",
        "symptoms": {"constipation", "bloating", "anorexia", "lethargy", "straining", "intestinal_obstruction"},
        "description": "Gastrointestinal obstruction from ingestion of gravel, pebbles, or large bark substrate particles during ambush feeding in Ceratophrys species.",
        "description_ja": "ツノガエル属の待ち伏せ給餌時に砂利・小石・大型樹皮粒子を誤飲することによる消化管閉塞。",
        "urgency": "high",
        "recommended_tests": ["X線検査", "超音波検査", "腹部触診", "造影検査"],
        "causes": "Ceratophrys frogs are ambush predators that strike at prey with a wide gape, frequently ingesting substrate material. Gravel and pebbles are particularly dangerous. Bark chips and coconut fiber can also accumulate.",
        "causes_ja": "ツノガエルは大きな口で餌に飛びつく待ち伏せ捕食者であり、頻繁に床材を誤飲する。砂利・小石は特に危険。バークチップやヤシ殻繊維も蓄積しうる。",
        "pathophysiology": "Indigestible substrate accumulates in the stomach or intestine, causing mechanical obstruction. Prolonged obstruction leads to mucosal necrosis, bacterial translocation, and peritonitis.",
        "pathophysiology_ja": "不消化な床材が胃または腸に蓄積し、機械的閉塞を引き起こす。長期閉塞は粘膜壊死、細菌移行、腹膜炎に至る。",
        "treatment": "Mild impaction: fasting for 7-10 days in shallow lukewarm water (22-24°C) to encourage passage. Moderate: gentle abdominal massage. Severe: surgical removal under MS-222 anesthesia using atraumatic forceps or coeliotomy. Post-operative antibiotics and supportive care.",
        "treatment_ja": "軽度：浅い微温水（22-24°C）での7-10日間絶食で自然排出を促進。中等度：穏やかな腹部マッサージ。重度：MS-222麻酔下での非外傷性鉗子による除去または開腹術。術後抗菌薬と支持療法。",
        "prevention": "Use bare-bottom enclosure or fine sand only (for frogs >12 cm). Paper towels are safest. Never use gravel, pebbles, or large bark with Ceratophrys. Target-feed with tongs to minimize substrate contact.",
        "prevention_ja": "底面無床材またはファインサンドのみ使用（12 cm以上の個体）。ペーパータオルが最も安全。ツノガエルに砂利・小石・大型バークは使用禁止。ピンセット給餌で床材接触を最小化。",
        "prognosis": "Good if mild and substrate passes naturally. Guarded with surgical intervention. Poor if peritonitis develops.",
        "prognosis_ja": "軽度で自然排出すれば予後良好。外科的介入を要する場合は予後慎重。腹膜炎発生時は予後不良。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"puppy", "young", "adult"},
    },

    # ══════════════════════════════════════════════════════════════════
    # 新規追加: ヤドクガエル (Poison Dart Frog / Dendrobatidae) 関連疾患
    # ══════════════════════════════════════════════════════════════════
    {
        "name": "Dendrobatid Chytridiomycosis (Bd - Dart Frog)",
        "name_ja": "ヤドクガエルツボカビ症",
        "symptoms": {"skin_shedding", "excessive_shedding", "skin_thickening", "lethargy", "anorexia", "weight_loss", "abnormal_posture", "loss_of_righting_reflex", "sudden_death"},
        "description": "Chytridiomycosis in poison dart frogs (Dendrobates, Phyllobates, Epipedobates spp.) with species-specific treatment protocols. Dart frogs are highly susceptible due to their thin, permeable skin.",
        "description_ja": "ヤドクガエル（Dendrobates, Phyllobates, Epipedobates属）におけるツボカビ症。薄い透過性の皮膚のため特に感受性が高く、種固有の治療プロトコルが必要。",
        "urgency": "emergency",
        "recommended_tests": ["皮膚スワブPCR", "皮膚スクレイピング", "組織病理検査"],
        "causes": "Infection by Batrachochytrium dendrobatidis (Bd) zoospores. Dart frogs are among the most susceptible amphibians due to their thin skin and reliance on cutaneous antimicrobial peptides and skin microbiome for defense.",
        "causes_ja": "ツボカビ菌（Bd）遊走子による感染。ヤドクガエルは薄い皮膚と皮膚抗菌ペプチド・皮膚マイクロバイオームへの防御依存のため、最も感受性の高い両生類の一つ。",
        "pathophysiology": "Bd zoospores infect keratinized epithelial cells, disrupting cutaneous electrolyte transport (Na+/K+ ATPase). In dart frogs, the thin epidermis allows rapid fungal penetration. Osmotic imbalance leads to cardiac arrest.",
        "pathophysiology_ja": "Bd遊走子が角化上皮細胞に感染し、皮膚電解質輸送（Na+/K+ ATPase）を障害。ヤドクガエルの薄い表皮は真菌の急速な侵入を許容。浸透圧不均衡が心停止を引き起こす。",
        "treatment": "Itraconazole bath: 0.01% solution (10 mg/mL diluted 1:100) for 5 minutes daily for 10-11 days. Alternatively, voriconazole bath (1.25 μg/mL for 5 min daily for 10 days). Raise ambient temperature to 25-26°C during treatment. PCR re-test 2 weeks post-treatment; repeat if positive.",
        "treatment_ja": "イトラコナゾール浴：0.01%溶液（10 mg/mL を1:100希釈）5分間/日 10-11日間。代替：ボリコナゾール浴（1.25 μg/mL 5分/日 10日間）。治療中は環境温度を25-26°Cに上昇。治療後2週間でPCR再検；陽性の場合は再治療。",
        "prevention": "Quarantine all new frogs for 60 days with PCR testing at intake and before release. Maintain vivarium temperature 24-27°C. Strict hygiene between enclosures. Bioactive vivarium setup supports beneficial skin microbiome.",
        "prevention_ja": "全新規個体を60日間検疫し、受入時と放出前にPCR検査。飼育温度24-27°C維持。飼育容器間の厳格な衛生管理。バイオアクティブビバリウム設計で有益な皮膚マイクロバイオームを維持。",
        "prognosis": "Good with early detection and itraconazole treatment (cure rate ~75-85%). Fatal if untreated. Some species show partial resistance through skin antimicrobial peptides.",
        "prognosis_ja": "早期発見とイトラコナゾール治療で予後良好（治癒率75-85%程度）。未治療では致死的。一部の種は皮膚抗菌ペプチドによる部分的抵抗性を示す。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"puppy", "young", "adult", "senior"},
    },
    {
        "name": "Dart Frog Spindly Leg Syndrome (SLS)",
        "name_ja": "ヤドクガエルスピンドリーレッグ症候群",
        "symptoms": {"spindly_legs", "limb_deformity", "failure_to_thrive", "weakness", "inability_to_feed", "stunted_growth"},
        "description": "Developmental disorder in captive-bred dendrobatid froglets characterized by thin, malformed limbs that cannot support the animal's weight. A major cause of mortality in dart frog breeding programs.",
        "description_ja": "飼育下繁殖ヤドクガエル幼体に発生する発達障害。体重を支えられない細く変形した四肢が特徴。ヤドクガエル繁殖プログラムにおける主要死因。",
        "urgency": "moderate",
        "recommended_tests": ["X線検査", "栄養分析", "水質検査", "親個体の栄養状態評価"],
        "causes": "Multifactorial: maternal nutritional deficiency (calcium, vitamin D3, vitamin A), inadequate tadpole nutrition, inappropriate water parameters during metamorphosis, genetic factors, and UV-B deficiency.",
        "causes_ja": "多因子性：母体の栄養不足（カルシウム、ビタミンD3、ビタミンA）、オタマジャクシの栄養不足、変態期の不適切な水質パラメータ、遺伝的要因、UV-B不足。",
        "pathophysiology": "Insufficient calcium and vitamin D3 during the critical metamorphic period impairs proper ossification of developing limbs. Myopathy from nutritional deficiency further weakens musculature. Affected froglets cannot hunt or move normally.",
        "pathophysiology_ja": "変態の重要な時期におけるカルシウムとビタミンD3の不足が発達中の四肢の正常な骨化を障害。栄養欠乏による筋障害がさらに筋肉を弱化。罹患幼体は正常な捕食・運動ができない。",
        "treatment": "No effective treatment once malformation occurs. Supportive care: hand-feeding with calcium-dusted springtails, shallow water for easy access. Euthanasia should be considered for severely affected animals unable to feed.",
        "treatment_ja": "変形が発生した後の有効な治療法はない。支持療法：カルシウムダスティングしたトビムシの手動給餌、容易にアクセスできる浅い水場の提供。自力摂食不能な重症個体には安楽死を検討。",
        "prevention": "Ensure breeding adults receive calcium+D3 supplementation 2-3x weekly. Supplement tadpole water with calcium. Maintain UV-B lighting for parents. Feed tadpoles high-quality spirulina-based food. Avoid inbreeding.",
        "prevention_ja": "繁殖成体にカルシウム+D3を週2-3回補給。オタマジャクシの水にカルシウムを添加。親個体にUV-B照明を提供。オタマジャクシに高品質スピルリナベースの餌を給与。近親交配の回避。",
        "prognosis": "Poor for affected froglets; most do not survive long-term. Prevention is the primary strategy. Breeding colony prognosis is good with proper nutritional management.",
        "prognosis_ja": "罹患幼体の予後は不良；多くは長期生存しない。予防が主要な戦略。適切な栄養管理で繁殖コロニーの予後は良好。",
        "onset_pattern": {"acute"},
        "age_predisposition": {"puppy"},
    },
    {
        "name": "Dart Frog Enteric Protozoal Infection",
        "name_ja": "ヤドクガエル腸管原虫感染症",
        "symptoms": {"weight_loss", "diarrhea", "anorexia", "lethargy", "bloating", "dehydration"},
        "description": "Gastrointestinal protozoal infections (retortamonads, diplomonads, flagellates) in captive poison dart frogs, often exacerbated by stress or immunosuppression.",
        "description_ja": "飼育下ヤドクガエルにおける消化管原虫感染（レトルタモナス、ディプロモナス、鞭毛虫類）。ストレスや免疫抑制により増悪。",
        "urgency": "moderate",
        "recommended_tests": ["糞便直接鏡検", "糞便浮遊法", "糞便塗抹染色"],
        "causes": "Overgrowth of commensal gastrointestinal protozoa (retortamonads, diplomonads, trichomonads) in stressed or immunosuppressed frogs. Newly imported or recently transported frogs are particularly susceptible.",
        "causes_ja": "ストレスまたは免疫抑制下のカエルにおける常在消化管原虫（レトルタモナス、ディプロモナス、トリコモナス）の過剰増殖。新規輸入または輸送直後の個体は特に感受性が高い。",
        "pathophysiology": "Protozoa proliferate in the intestinal lumen under conditions of stress-induced immunosuppression. Heavy burdens cause mucosal inflammation, malabsorption, and secondary bacterial invasion.",
        "pathophysiology_ja": "ストレス誘発性免疫抑制下で原虫が腸管内で増殖。高度感染は粘膜炎症、吸収不良、二次的細菌侵入を引き起こす。",
        "treatment": "Metronidazole (10 mg/kg PO q24h for 5-10 days) to reduce protozoan burden. Alternatively, fenbendazole (50 mg/kg PO, repeat in 14 days) for flagellates. Optimize husbandry to reduce stress. Probiotic supplementation may help restore gut flora.",
        "treatment_ja": "メトロニダゾール（10 mg/kg PO 1日1回 5-10日間）で原虫量を減少。代替：フェンベンダゾール（50 mg/kg PO、14日後再投与）で鞭毛虫に対応。ストレス軽減のため飼育環境を最適化。プロバイオティクス補給で腸内細菌叢の回復を促進。",
        "prevention": "Quarantine new arrivals for 30-60 days. Fecal screening at intake. Maintain stable vivarium conditions (temperature 24-27°C, humidity 80-100%). Minimize handling stress.",
        "prevention_ja": "新規個体を30-60日間検疫。受入時に糞便スクリーニング。安定したビバリウム条件の維持（温度24-27°C、湿度80-100%）。ハンドリングストレスの最小化。",
        "prognosis": "Good with appropriate treatment and husbandry optimization. Recurrence possible if stress factors are not addressed.",
        "prognosis_ja": "適切な治療と飼育環境最適化で予後良好。ストレス要因が未解決の場合は再発の可能性あり。",
        "onset_pattern": {"subacute", "chronic"},
        "age_predisposition": {"puppy", "young", "adult"},
    },
    {
        "name": "Short Tongue Syndrome (Hypovitaminosis A - Anuran)",
        "name_ja": "短舌症候群（低ビタミンA症）",
        "symptoms": {"anorexia", "weight_loss", "inability_to_feed", "lethargy", "cloudy_eyes", "skin_lesions", "failure_to_thrive"},
        "description": "Squamous metaplasia of the tongue caused by vitamin A deficiency in captive frogs, particularly dart frogs. Affected frogs cannot extend their tongue to capture prey, leading to starvation.",
        "description_ja": "飼育下カエル（特にヤドクガエル）におけるビタミンA欠乏による舌の扁平上皮化生。罹患個体は舌を伸ばして餌を捕獲できず、飢餓に至る。",
        "urgency": "moderate",
        "recommended_tests": ["口腔内検査", "血清ビタミンA測定", "肝臓生検（重症例）"],
        "causes": "Captive frogs cannot synthesize carotenoids or convert beta-carotene to retinol efficiently. Feeder insects (fruit flies, crickets) are naturally deficient in preformed vitamin A. Without supplementation, deficiency develops within months.",
        "causes_ja": "飼育下のカエルはカロテノイドを合成できず、β-カロテンからレチノールへの変換効率も低い。餌昆虫（ショウジョウバエ、コオロギ）はプレフォームドビタミンAが自然に欠乏。サプリメントなしでは数ヶ月で欠乏症が発症。",
        "pathophysiology": "Vitamin A deficiency causes squamous metaplasia of mucosal epithelium throughout the body. In the tongue, this results in loss of the specialized sticky mucus-secreting epithelium, rendering the tongue non-functional for prey capture. Also affects eyes, reproductive organs, and immune function.",
        "pathophysiology_ja": "ビタミンA欠乏は全身の粘膜上皮の扁平上皮化生を引き起こす。舌では特殊な粘着性粘液分泌上皮が失われ、舌が餌捕獲に機能しなくなる。眼・生殖器・免疫機能にも影響。",
        "treatment": "Vitamin A supplementation: topical application of vitamin A (retinol) solution on dorsal skin (absorbed transcutaneously). Dust feeders with preformed vitamin A supplement (Repashy Vitamin A) once monthly. Hand-feed affected frogs with vitamin A-dusted springtails until tongue function recovers (4-8 weeks).",
        "treatment_ja": "ビタミンA補給：ビタミンA（レチノール）溶液の背部皮膚への局所塗布（経皮吸収）。月1回プレフォームドビタミンAサプリメント（Repashy Vitamin A）で餌をダスティング。舌機能が回復するまで（4-8週間）ビタミンAダスティングしたトビムシを手動給餌。",
        "prevention": "Monthly vitamin A (preformed retinol) supplementation for all captive frogs. Gut-load feeder insects with vitamin A-rich foods. Avoid over-supplementation (risk of hypervitaminosis A).",
        "prevention_ja": "全飼育カエルへの月1回のビタミンA（プレフォームドレチノール）補給。餌昆虫にビタミンA豊富な飼料でガットローディング。過剰補給の回避（ビタミンA過剰症のリスク）。",
        "prognosis": "Good if caught early; tongue function typically recovers within 4-8 weeks of supplementation. Poor if chronic and secondary organ damage has occurred.",
        "prognosis_ja": "早期発見で予後良好；舌機能は補給開始後4-8週間で回復。慢性化し二次的臓器障害が発生した場合は予後不良。",
        "onset_pattern": {"chronic"},
        "age_predisposition": {"young", "adult", "senior"},
    },
    {
        "name": "Hypervitaminosis A (Vitamin A Toxicity)",
        "name_ja": "ビタミンA過剰症",
        "symptoms": {"skin_ulcers", "skin_thickening", "limb_deformity", "bone_deformity", "cloudy_eyes", "lethargy", "anorexia"},
        "description": "Vitamin A toxicity from excessive supplementation in captive amphibians. Causes skin ulceration, skeletal deformities, and paradoxically, signs mimicking metabolic bone disease due to interference with vitamins D, E, and K.",
        "description_ja": "飼育下両生類における過剰サプリメントによるビタミンA中毒。皮膚潰瘍、骨格変形を引き起こし、ビタミンD・E・K の吸収阻害により代謝性骨疾患類似症状を呈する。",
        "urgency": "moderate",
        "recommended_tests": ["血清ビタミンA測定", "X線検査", "肝機能検査"],
        "causes": "Over-supplementation with preformed vitamin A (retinol). Most common when keepers dust feeders too frequently or use high-concentration vitamin A products. Froglets that are not producing eggs are particularly susceptible as they cannot excrete excess through reproduction.",
        "causes_ja": "プレフォームドビタミンA（レチノール）の過剰サプリメント。高濃度ビタミンA製品の使用や頻繁なダスティングが原因。産卵しない幼体は過剰分を生殖を通じて排泄できず特に感受性が高い。",
        "pathophysiology": "Excess retinol accumulates in the liver, causing hepatotoxicity. It also interferes with the absorption and utilization of vitamins D, E, and K, leading to secondary metabolic bone disease, coagulopathy, and oxidative stress.",
        "pathophysiology_ja": "過剰レチノールが肝臓に蓄積し、肝毒性を引き起こす。ビタミンD・E・Kの吸収・利用を阻害し、二次的代謝性骨疾患、凝固障害、酸化ストレスを招く。",
        "treatment": "Discontinue vitamin A supplementation immediately. Supportive care with vitamin D3 and calcium supplementation. Monitor liver function. Recovery may take several months.",
        "treatment_ja": "直ちにビタミンAサプリメントを中止。ビタミンD3・カルシウム補給による支持療法。肝機能モニタリング。回復には数ヶ月を要する。",
        "prevention": "Supplement vitamin A no more than once monthly. Use appropriate concentrations. Track supplementation schedule. Carotenoid-based supplements are safer as excess is excreted.",
        "prevention_ja": "ビタミンA補給は月1回以下。適切な濃度を使用。補給スケジュールを記録。カロテノイドベースのサプリメントは過剰分が排泄されるため安全。",
        "prognosis": "Fair to good if detected early and supplementation is stopped. Skeletal deformities are permanent.",
        "prognosis_ja": "早期発見とサプリメント中止で予後はやや良好。骨格変形は不可逆的。",
        "onset_pattern": {"chronic"},
        "age_predisposition": {"puppy", "young", "adult"},
    },

    # ══════════════════════════════════════════════════════════════════
    # 新規追加: アフリカツメガエル (Xenopus laevis) 関連疾患
    # ══════════════════════════════════════════════════════════════════
    {
        "name": "Xenopus Dropsy (Balloon Frog Syndrome)",
        "name_ja": "アフリカツメガエル水腫症（バルーンフロッグ症候群）",
        "symptoms": {"edema", "generalized_swelling", "bloating", "lymph_sac_edema", "lethargy", "anorexia", "regurgitation", "ascites", "coelomic_distension"},
        "description": "Severe subcutaneous fluid accumulation in African clawed frogs (Xenopus laevis) and dwarf clawed frogs (Hymenochirus spp.), commonly called 'balloon frog syndrome'. Often associated with bacterial septicemia or renal failure.",
        "description_ja": "アフリカツメガエル（Xenopus laevis）およびコビトツメガエル（Hymenochirus属）に発生する重度の皮下液貯留。「バルーンフロッグ症候群」と呼ばれ、細菌性敗血症や腎不全に関連。",
        "urgency": "high",
        "recommended_tests": ["体腔液穿刺・分析", "細菌培養", "血液検査（BUN・UA）", "超音波検査"],
        "causes": "Bacterial septicemia (Aeromonas hydrophila, Pseudomonas spp.), chronic renal failure, hepatic disease, or chronic poor water quality. Bacterial form appears suddenly; diet-related form develops gradually.",
        "causes_ja": "細菌性敗血症（Aeromonas hydrophila、Pseudomonas属）、慢性腎不全、肝疾患、慢性的水質不良。細菌性は急性発症、食事関連は徐々に進行。",
        "pathophysiology": "Bacterial toxins increase vascular permeability, causing fluid to leak into subcutaneous lymph sacs and coelomic cavity. In renal failure, inability to excrete water leads to fluid overload. Hypoalbuminemia from hepatic disease decreases oncotic pressure.",
        "pathophysiology_ja": "細菌毒素が血管透過性を亢進させ、皮下リンパ嚢と体腔に液漏出。腎不全では水排泄不能による体液過負荷。肝疾患による低アルブミン血症が膠質浸透圧を低下。",
        "treatment": "Percutaneous fluid drainage under sterile conditions. Antibiotics: enrofloxacin (5 mg/kg SC q24h) or trimethoprim-sulfamethoxazole bath. Furosemide (2-5 mg/kg topical). For Xenopus, repeated skin puncture to release fluid has been reported to allow survival for years. Do NOT raise water temperature.",
        "treatment_ja": "無菌条件下での経皮的排液。抗菌薬：エンロフロキサシン（5 mg/kg SC 1日1回）またはトリメトプリム-スルファメトキサゾール浴。フロセミド（2-5 mg/kg 経皮）。Xenopusでは反復的な皮膚穿刺による排液で数年間の生存報告あり。水温を上げてはならない。",
        "prevention": "Three-stage water filtration. Weekly 30% water changes. Balanced diet. Avoid overfeeding. Maintain water temperature below 24°C for Xenopus.",
        "prevention_ja": "三段階水ろ過。週30%換水。バランスのとれた食事。過食回避。Xenopusの水温は24°C以下を維持。",
        "prognosis": "Guarded to poor for bacterial form. Diet-related form has better prognosis with early intervention. Many cases require lifelong management with periodic fluid drainage.",
        "prognosis_ja": "細菌性では予後慎重〜不良。食事関連は早期介入で予後改善。多くの症例は定期的排液を伴う生涯管理を要する。",
        "onset_pattern": {"acute", "chronic"},
        "age_predisposition": {"adult", "senior"},
    },
    {
        "name": "Xenopus Pseudocapillaroides Skin Infection",
        "name_ja": "アフリカツメガエル皮膚線虫症",
        "symptoms": {"excessive_shedding", "skin_discoloration", "skin_ulceration", "weight_loss", "skin_lesions", "dermatitis"},
        "description": "Epidermal nematode infection by Pseudocapillaroides xenopi in African clawed frogs, causing chronic skin disease with excessive shedding and ulceration.",
        "description_ja": "アフリカツメガエルにおけるPseudocapillaroides xenopiによる表皮線虫感染症。慢性皮膚疾患で過剰脱皮と潰瘍形成を引き起こす。",
        "urgency": "moderate",
        "recommended_tests": ["皮膚スクレイピング", "皮膚生検・組織病理", "顕微鏡検査"],
        "causes": "Infection by the nematode Pseudocapillaroides xenopi, which lives within the epidermis. Affects both free-ranging and captive African clawed frogs. Transmission route is not fully understood but likely involves direct contact or environmental contamination.",
        "causes_ja": "表皮内に寄生する線虫Pseudocapillaroides xenopiによる感染。野生・飼育下いずれのアフリカツメガエルにも発生。伝播経路は完全には解明されていないが、直接接触または環境汚染を介すると考えられる。",
        "pathophysiology": "Nematodes reside within the epidermal layers, causing chronic inflammation, hyperkeratosis, and progressive skin damage. Heavy infections lead to ulceration, secondary bacterial infection, and loss of body condition.",
        "pathophysiology_ja": "線虫が表皮層内に寄生し、慢性炎症・角質増殖・進行性皮膚損傷を引き起こす。高度感染では潰瘍形成、二次的細菌感染、体格悪化に至る。",
        "treatment": "Thiabendazole (50-100 mg/kg PO) combined with levamisole (5 mg/kg SC), then levamisole (10 mg/kg SC) at 10 and 20 days. Alternatively, ivermectin bath (10 mg/L) or levamisole bath (100-300 mg/L) for 1 hour weekly for 3-4 treatments.",
        "treatment_ja": "チアベンダゾール（50-100 mg/kg PO）とレバミゾール（5 mg/kg SC）の併用、その後10日目と20日目にレバミゾール（10 mg/kg SC）。代替：イベルメクチン浴（10 mg/L）またはレバミゾール浴（100-300 mg/L）1時間/週 3-4回。",
        "prevention": "Quarantine new Xenopus for 30 days with skin scraping examination. Avoid mixing wild-caught and captive-bred frogs. Maintain clean water conditions.",
        "prevention_ja": "新規Xenopusを30日間検疫し皮膚スクレイピング検査。野生捕獲個体と飼育下繁殖個体の混合回避。清浄な水質の維持。",
        "prognosis": "Good with appropriate anthelmintic treatment. Reinfection possible in contaminated environments.",
        "prognosis_ja": "適切な駆虫薬治療で予後良好。汚染環境では再感染の可能性あり。",
        "onset_pattern": {"chronic"},
        "age_predisposition": {"adult", "senior"},
    },

    # ══════════════════════════════════════════════════════════════════
    # 新規追加: アマガエル (Tree Frog) 関連疾患
    # ══════════════════════════════════════════════════════════════════
    {
        "name": "Tree Frog Bacterial Pneumonia",
        "name_ja": "アマガエル細菌性肺炎",
        "symptoms": {"dyspnea", "open_mouth_breathing", "lethargy", "anorexia", "excessive_mucus", "weight_loss", "abnormal_posture"},
        "description": "Bacterial pneumonia in arboreal frogs (Hylidae, Rhacophoridae) caused by opportunistic bacteria secondary to cool, damp conditions with poor ventilation.",
        "description_ja": "樹上性カエル（アマガエル科、アオガエル科）における細菌性肺炎。低温多湿・換気不良環境での日和見細菌が原因。",
        "urgency": "high",
        "recommended_tests": ["X線検査", "気管洗浄液培養", "血液検査", "細菌培養・感受性試験"],
        "causes": "Opportunistic bacterial infection (Aeromonas, Pseudomonas, Klebsiella) of the lungs, precipitated by cool temperatures below species-specific requirements, poor ventilation (less than 1-2 air changes/hour), chronic high humidity without adequate airflow, and immunosuppression.",
        "causes_ja": "低温（種固有の適温以下）、換気不良（1-2回/時間未満の空気交換）、適切な気流のない慢性高湿度、免疫抑制を背景とした日和見細菌（Aeromonas、Pseudomonas、Klebsiella）による肺感染。",
        "pathophysiology": "Bacteria colonize pulmonary epithelium, causing suppurative inflammation, exudate accumulation, and impaired gas exchange. Amphibians rely heavily on cutaneous respiration, so pulmonary compromise is often advanced before clinical signs appear.",
        "pathophysiology_ja": "細菌が肺上皮に定着し、化膿性炎症・滲出液蓄積・ガス交換障害を引き起こす。両生類は皮膚呼吸への依存度が高いため、臨床症状が出現する前に肺障害が進行していることが多い。",
        "treatment": "Enrofloxacin (5-10 mg/kg SC or IM q24h for 14-21 days) or trimethoprim-sulfa (15 mg/kg PO q24h). Nebulization with F10SC (1:250 dilution) for 15-30 min twice daily. Raise temperature to upper end of species-specific range. Ensure adequate ventilation. Supportive care with fluids.",
        "treatment_ja": "エンロフロキサシン（5-10 mg/kg SC/IM 1日1回 14-21日間）またはトリメトプリム-スルファ（15 mg/kg PO 1日1回）。F10SC（1:250希釈）のネブライゼーション15-30分 1日2回。温度を種固有の適温上限に上昇。十分な換気の確保。輸液による支持療法。",
        "prevention": "Maintain species-appropriate temperature (most tropical tree frogs: 24-28°C). Ensure vivarium has adequate ventilation (screen top or ventilation panels). Balance humidity with airflow. Quarantine new animals.",
        "prevention_ja": "種に適した温度の維持（熱帯性アマガエル：24-28°C）。ビバリウムの適切な換気確保（スクリーントップまたは換気パネル）。湿度と気流のバランス。新規個体の検疫。",
        "prognosis": "Fair with early aggressive treatment. Poor if diagnosis is delayed, as amphibians often present late due to reliance on cutaneous respiration.",
        "prognosis_ja": "早期の積極的治療で予後はやや良好。皮膚呼吸への依存により受診が遅れる傾向があり、遅延診断では予後不良。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"young", "adult", "senior"},
    },
    {
        "name": "Amphibian Collagenoma",
        "name_ja": "両生類コラゲノーマ（膠原線維腫）",
        "symptoms": {"skin_masses", "raised_nodules", "skin_nodules", "mass_growth"},
        "description": "Benign collagenous skin tumor reported in African clawed frogs (Xenopus laevis) and other species. Presents as firm, well-circumscribed dermal nodules (PMC4752032).",
        "description_ja": "アフリカツメガエル（Xenopus laevis）などに報告される良性の膠原線維性皮膚腫瘍。硬く境界明瞭な真皮結節として出現（PMC4752032）。",
        "urgency": "low",
        "recommended_tests": ["細胞診", "皮膚生検・組織病理", "X線検査"],
        "causes": "Etiology is unclear. Possibly related to chronic irritation, viral factors, or age-related changes. Reported primarily in older captive Xenopus laevis.",
        "causes_ja": "病因は不明。慢性刺激、ウイルス要因、加齢変化との関連が推測される。主に高齢飼育下Xenopus laevisで報告。",
        "pathophysiology": "Benign proliferation of collagen-producing fibroblasts in the dermis. Masses are well-circumscribed and do not metastasize but can grow to impair movement or feeding if located near the mouth or limbs.",
        "pathophysiology_ja": "真皮におけるコラーゲン産生線維芽細胞の良性増殖。腫瘤は境界明瞭で転移しないが、口腔や四肢近傍に発生すると運動や摂食を障害しうる。",
        "treatment": "Surgical excision under MS-222 anesthesia if mass interferes with function. Monitor small, non-obstructive masses without intervention. Post-surgical wound care with clean water and topical antibiotic.",
        "treatment_ja": "腫瘤が機能を障害する場合はMS-222麻酔下での外科的切除。小型で非閉塞性の腫瘤は介入なしで経過観察。術後創傷ケアとして清浄水と局所抗菌薬。",
        "prevention": "No specific prevention known. Regular health monitoring of aging captive frogs.",
        "prevention_ja": "特異的な予防法は不明。高齢飼育カエルの定期的健康モニタリング。",
        "prognosis": "Excellent. Benign tumors with no metastatic potential. Surgical excision is curative if needed.",
        "prognosis_ja": "予後良好。転移能のない良性腫瘍。必要に応じた外科的切除で治癒。",
        "onset_pattern": {"chronic"},
        "age_predisposition": {"adult", "senior"},
    },

    # ══════════════════════════════════════════════════════════════════
    # 新規追加: ファイアサラマンダー・イモリ類固有疾患
    # ══════════════════════════════════════════════════════════════════
    {
        "name": "Bsal Ulcerative Skin Disease (Fire Salamander)",
        "name_ja": "Bsal潰瘍性皮膚疾患（ファイアサラマンダー）",
        "symptoms": {"skin_ulcers", "skin_lesions", "skin_erosion", "anorexia", "lethargy", "skin_sloughing", "rapid_death"},
        "description": "Batrachochytrium salamandrivorans (Bsal) causes rapidly progressing deep skin ulceration in salamanders, especially fire salamanders (Salamandra salamandra). Has caused >99% mortality in European fire salamander populations.",
        "description_ja": "Batrachochytrium salamandrivorans（Bsal）によるサラマンダー（特にファイアサラマンダー Salamandra salamandra）の急速進行性深部皮膚潰瘍。欧州のファイアサラマンダー個体群で99%以上の致死率を記録。",
        "urgency": "emergency",
        "recommended_tests": ["皮膚スワブPCR（Bsal特異的）", "組織病理検査", "皮膚スクレイピング"],
        "causes": "Infection by the chytrid fungus Batrachochytrium salamandrivorans (Bsal), which was likely introduced from Asia. Unlike Bd, Bsal is primarily lethal to caudates (salamanders/newts). Optimal growth at 10-15°C. Asian salamanders (Cynops, Tylototriton) are asymptomatic carriers.",
        "causes_ja": "ツボカビ菌Batrachochytrium salamandrivorans（Bsal）の感染。アジア由来と推定。Bdと異なり、Bsalは主に有尾目（サラマンダー/イモリ）に致死的。至適増殖温度10-15°C。アジア産サラマンダー（アカハライモリ属等）は無症候性キャリア。",
        "pathophysiology": "Bsal produces multifocal erosive skin lesions that penetrate deeply into the dermis, unlike the superficial keratinized layer invasion of Bd. Rapid skin destruction leads to loss of osmotic regulation, secondary bacterial septicemia, and death within 2 weeks of clinical signs.",
        "pathophysiology_ja": "BsalはBdの表層角質層侵入と異なり、真皮深層に達する多巣性びらん性皮膚病変を産生。急速な皮膚破壊が浸透圧調節機能の喪失、二次的細菌性敗血症を招き、臨床症状出現後2週間以内に死亡。",
        "treatment": "Heat treatment: maintain at 25°C for 10 days (Bsal cannot grow above 25°C). Combined with voriconazole bath (12.5 μg/mL for 5 min daily for 10 days) or polymyxin E/voriconazole combination. Itraconazole alone is less effective against Bsal than Bd.",
        "treatment_ja": "温熱療法：25°Cで10日間維持（Bsalは25°C以上で増殖不能）。ボリコナゾール浴（12.5 μg/mL 5分/日 10日間）またはポリミキシンE/ボリコナゾール併用療法を併用。イトラコナゾール単独はBsalに対してBdほど有効ではない。",
        "prevention": "Strict import controls on Asian caudates. PCR screening of all traded salamanders. Quarantine at 25°C for 2 weeks (diagnostic and therapeutic). Do not mix European and Asian salamander species. Disinfect equipment with 1% Virkon-S.",
        "prevention_ja": "アジア産有尾目の厳格な輸入規制。全流通サラマンダーのPCRスクリーニング。25°Cで2週間の検疫（診断的かつ治療的）。欧州産とアジア産サラマンダーの混合飼育禁止。1%ビルコンSによる器具消毒。",
        "prognosis": "Very poor without treatment in susceptible species (>99% mortality in fire salamanders). Good if heat treatment is initiated before extensive skin damage. Asian species typically survive as carriers.",
        "prognosis_ja": "感受性種では未治療で予後極めて不良（ファイアサラマンダーで99%以上の致死率）。広範な皮膚損傷前に温熱療法を開始すれば予後良好。アジア産種はキャリアとして通常生存。",
        "onset_pattern": {"acute"},
        "age_predisposition": {"puppy", "young", "adult", "senior"},
    },
    {
        "name": "Newt Iodine Deficiency Goiter",
        "name_ja": "イモリヨウ素欠乏性甲状腺腫",
        "symptoms": {"goiter", "thyroid_enlargement", "neck_swelling", "lethargy", "metamorphosis_failure", "failure_to_metamorphose", "obesity", "stunted_growth"},
        "description": "Thyroid enlargement in captive newts and salamanders due to dietary iodine deficiency, leading to impaired metamorphosis in larvae and metabolic dysfunction in adults.",
        "description_ja": "飼育下イモリ・サラマンダーにおける食事性ヨウ素欠乏による甲状腺腫大。幼生の変態障害と成体の代謝機能障害を引き起こす。",
        "urgency": "moderate",
        "recommended_tests": ["身体検査（頸部触診）", "超音波検査", "甲状腺ホルモン測定", "X線検査"],
        "causes": "Dietary iodine deficiency in captive-bred amphibians fed exclusively on insects or invertebrates without mineral supplementation. Particularly common in fully aquatic species (Cynops, Notophthalmus) fed only on bloodworms or brine shrimp.",
        "causes_ja": "ミネラルサプリメントなしの昆虫・無脊椎動物のみの給餌による飼育下両生類の食事性ヨウ素欠乏。特にアカハタウオ・イモリなど完全水生種でのアカムシ・ブラインシュリンプのみの給餌で多発。",
        "pathophysiology": "Iodine deficiency impairs thyroid hormone (T3/T4) synthesis. Compensatory TSH elevation drives thyroid hyperplasia (goiter). In larvae, T3 deficiency blocks metamorphosis. In adults, hypothyroidism causes metabolic slowing, weight gain, and lethargy.",
        "pathophysiology_ja": "ヨウ素欠乏が甲状腺ホルモン（T3/T4）合成を障害。代償性TSH上昇が甲状腺過形成（甲状腺腫）を誘導。幼生ではT3欠乏が変態を阻害。成体では甲状腺機能低下が代謝低下・体重増加・無気力を引き起こす。",
        "treatment": "Iodine supplementation: add iodized salt to water (0.5 mg/L) for aquatic species, or gut-load feeder insects with iodine-containing marine algae. Thyroid hormone supplementation (levothyroxine 0.02 mg/kg PO) in severe cases. Goiter usually regresses with supplementation.",
        "treatment_ja": "ヨウ素補給：水生種には水にヨウ素添加塩（0.5 mg/L）を添加、または餌昆虫にヨウ素含有海藻でガットローディング。重症例ではレボチロキシン（0.02 mg/kg PO）による甲状腺ホルモン補充。サプリメントで甲状腺腫は通常退縮。",
        "prevention": "Include iodine in mineral supplementation routine. Feed varied diet including whole fish (for aquatic species) which contains natural iodine. Use marine-algae-based gut-loading products.",
        "prevention_ja": "ミネラルサプリメントにヨウ素を含める。天然ヨウ素を含む全魚（水生種用）を含む多様な食事。海藻ベースのガットローディング製品の使用。",
        "prognosis": "Good with iodine supplementation; goiter typically regresses within 4-8 weeks. Metamorphosis failure in larvae may be irreversible if treatment is delayed.",
        "prognosis_ja": "ヨウ素補給で予後良好；甲状腺腫は通常4-8週間で退縮。幼生の変態障害は治療遅延により不可逆的となる場合がある。",
        "onset_pattern": {"chronic"},
        "age_predisposition": {"puppy", "young", "adult"},
    },

    # ══════════════════════════════════════════════════════════════════
    # 新規追加: 飼育環境関連疾患（全両生類共通）
    # ══════════════════════════════════════════════════════════════════
    {
        "name": "Amphibian Chromomycosis (Pigmented Fungal Infection)",
        "name_ja": "両生類クロモミコーシス（色素性真菌感染症）",
        "symptoms": {"skin_lesions", "dark_skin_nodules", "skin_ulcers", "granulomatous_lesions", "lethargy", "anorexia", "neurological_signs", "sudden_death"},
        "description": "Infection with pigmented fungi (Dermatiaceae family: Fonsecaea, Cladophialophora, Exophiala spp.) through broken skin. Common and often fatal in captive amphibians. Can spread to the CNS.",
        "description_ja": "損傷皮膚を介した色素性真菌（Dermatiaceae科：Fonsecaea、Cladophialophora、Exophiala属）による感染。飼育下両生類で一般的かつ致死的。中枢神経系に拡大しうる。",
        "urgency": "high",
        "recommended_tests": ["皮膚生検・組織病理（PAS・GMS染色）", "真菌培養", "PCR検査"],
        "causes": "Pigmented fungi from the family Dermatiaceae found in organic matter (topsoil, decaying plant material, bark). Infection occurs through breaks in the skin—cuts, abrasions, or insect bites. Poor hygiene and damp substrate increase risk. Zoonotic potential exists.",
        "causes_ja": "有機物（表土、腐敗植物、樹皮）に存在するDermatiaceae科の色素性真菌。皮膚の損傷部（切創、擦傷、虫刺され）から感染。衛生不良と湿った床材がリスクを増大。人獣共通感染症の可能性あり。",
        "pathophysiology": "Fungal hyphae invade through damaged skin and form pigmented (dematiaceous) granulomas. Disease progresses from cutaneous lesions to subcutaneous spread and potentially hematogenous dissemination to the CNS. CNS involvement is invariably fatal.",
        "pathophysiology_ja": "真菌菌糸が損傷皮膚から侵入し、色素性（暗色分生子）肉芽腫を形成。疾患は皮膚病変から皮下への拡大、さらに血行性にCNSへの播種に進行する可能性がある。CNS浸潤は必ず致死的。",
        "treatment": "Antifungal therapy: itraconazole bath (0.01% for 5 min daily for 10-14 days) or voriconazole (topical or bath). Surgical debridement of localized lesions. Treatment is often unsuccessful once infection has disseminated. Handle affected animals with gloves (zoonotic risk).",
        "treatment_ja": "抗真菌療法：イトラコナゾール浴（0.01% 5分/日 10-14日間）またはボリコナゾール（局所または浴）。限局性病変の外科的デブリードマン。播種性感染では治療は多くの場合不成功。罹患個体はグローブを着用して取り扱い（人獣共通感染リスク）。",
        "prevention": "Maintain clean enclosures. Replace organic substrate regularly. Avoid bark and soil contaminated with decaying plant matter. Prevent skin injuries. Quarantine new animals.",
        "prevention_ja": "清潔な飼育環境の維持。有機床材の定期交換。腐敗植物で汚染された樹皮・土壌の回避。皮膚損傷の予防。新規個体の検疫。",
        "prognosis": "Poor to grave once systemic. Early localized lesions may respond to surgery + antifungals. CNS involvement is uniformly fatal. Mortality within 2 weeks if untreated.",
        "prognosis_ja": "全身性になると予後不良〜最悪。早期限局性病変は手術+抗真菌薬に反応しうる。CNS浸潤は一律に致死的。未治療では2週間以内に死亡。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"young", "adult", "senior"},
    },
    {
        "name": "Amphibian Rhabdias Pulmonary Nematodiasis",
        "name_ja": "両生類ラブジアス肺線虫症",
        "symptoms": {"dyspnea", "open_mouth_breathing", "weight_loss", "lethargy", "respiratory_distress", "excessive_mucus", "anorexia"},
        "description": "Pulmonary infection by Rhabdias lungworms, common in wild-caught and captive amphibians. Heavy burdens cause significant respiratory compromise.",
        "description_ja": "Rhabdias肺線虫による肺感染症。野生捕獲・飼育下両生類で一般的。高度寄生は重大な呼吸障害を引き起こす。",
        "urgency": "moderate",
        "recommended_tests": ["糞便検査（浮遊法・直接鏡検）", "気管洗浄", "X線検査"],
        "causes": "Infection by Rhabdias spp. lungworms with a direct life cycle. Free-living larvae in soil/substrate penetrate the skin or are ingested, migrate to the lungs. Captive amphibians on soil substrates are at highest risk. Autoinfection can maintain high parasite burdens.",
        "causes_ja": "直接生活環を持つRhabdias属肺線虫による感染。土壌/床材中の自由生活期幼虫が皮膚を貫通または経口摂取され、肺に移行。土壌床材上の飼育両生類は最もリスクが高い。自己感染により高い寄生虫量が維持されうる。",
        "pathophysiology": "Adult worms reside in the lungs, causing verminous pneumonia with mucoid exudate, eosinophilic inflammation, and impaired gas exchange. Heavy infections can occlude bronchi. Larval migration causes tissue damage in skin and viscera.",
        "pathophysiology_ja": "成虫が肺に寄生し、粘液性滲出液・好酸球性炎症・ガス交換障害を伴う寄生虫性肺炎を引き起こす。高度感染では気管支を閉塞。幼虫移行は皮膚と内臓に組織損傷を引き起こす。",
        "treatment": "Levamisole bath (100-300 mg/L for 1 hour, repeat weekly for 3 treatments) or ivermectin (0.2 mg/kg SC or topical, repeat in 14 days). Fenbendazole (50-100 mg/kg PO daily for 3-5 days). Change substrate to prevent reinfection.",
        "treatment_ja": "レバミゾール浴（100-300 mg/L 1時間、週1回 3回繰り返し）またはイベルメクチン（0.2 mg/kg SC/経皮、14日後再投与）。フェンベンダゾール（50-100 mg/kg PO 1日1回 3-5日間）。再感染防止のため床材を交換。",
        "prevention": "Quarantine and fecal examination of all new arrivals. Use non-soil substrates (foam, paper towel, sphagnum) for quarantine. Regular fecal screening of collection. Treat prophylactically if wild-caught.",
        "prevention_ja": "全新規個体の検疫と糞便検査。検疫にはスポンジ・ペーパータオル・水苔等の非土壌床材を使用。コレクションの定期的糞便スクリーニング。野生捕獲個体には予防的駆虫。",
        "prognosis": "Good with anthelmintic treatment. Reinfection common if substrate and husbandry are not addressed.",
        "prognosis_ja": "駆虫薬治療で予後良好。床材と飼育管理が改善されなければ再感染が一般的。",
        "onset_pattern": {"chronic"},
        "age_predisposition": {"young", "adult", "senior"},
    },
    {
        "name": "Amphibian Elizabethkingia Meningoencephalitis",
        "name_ja": "両生類エリザベスキンギア髄膜脳炎",
        "symptoms": {"neurological_signs", "incoordination", "seizures", "lethargy", "anorexia", "abnormal_posture", "sudden_death", "skin_redness"},
        "description": "Systemic infection and meningoencephalitis caused by Elizabethkingia meningoseptica (formerly Chryseobacterium) in captive amphibians. Particularly devastating in laboratory frog colonies.",
        "description_ja": "飼育下両生類におけるElizabethkingia meningoseptica（旧Chryseobacterium）による全身感染症と髄膜脳炎。実験用カエルコロニーで特に壊滅的。",
        "urgency": "emergency",
        "recommended_tests": ["細菌培養・感受性試験", "髄液分析", "組織病理検査", "血液検査"],
        "causes": "Elizabethkingia meningoseptica is an environmental bacterium found in water and soil. Opportunistic infection in immunosuppressed or stressed amphibians. Can cause outbreaks in laboratory and breeding colonies. Inherently resistant to many antibiotics.",
        "causes_ja": "Elizabethkingia meningosepticaは水・土壌に存在する環境細菌。免疫抑制またはストレス下の両生類における日和見感染。実験施設・繁殖コロニーで集団発生しうる。多くの抗菌薬に自然耐性。",
        "pathophysiology": "Bacteria invade through compromised mucous membranes or skin, causing bacteremia and crossing the blood-brain barrier to cause meningoencephalitis. Endotoxin production leads to septic shock. Intrinsic resistance to beta-lactams and aminoglycosides limits treatment options.",
        "pathophysiology_ja": "細菌が障害された粘膜または皮膚から侵入し、菌血症を起こし血液脳関門を通過して髄膜脳炎を引き起こす。エンドトキシン産生が敗血症性ショックに至る。β-ラクタム系・アミノグリコシド系への自然耐性が治療選択肢を制限。",
        "treatment": "Culture-directed therapy essential due to multidrug resistance. Often susceptible to: minocycline, trimethoprim-sulfamethoxazole, or fluoroquinolones. Enrofloxacin (10 mg/kg SC q24h) as empiric therapy. Supportive care with electrolyte management. Isolate affected animals immediately.",
        "treatment_ja": "多剤耐性のため培養感受性試験に基づく治療が不可欠。通常感受性のある薬剤：ミノサイクリン、トリメトプリム-スルファメトキサゾール、フルオロキノロン系。経験的治療としてエンロフロキサシン（10 mg/kg SC 1日1回）。電解質管理を伴う支持療法。罹患個体の即時隔離。",
        "prevention": "Maintain excellent water quality. Reduce stocking density. PCR or culture screening of water sources. Strict biosecurity between enclosures. UV sterilization of water supply for colony management.",
        "prevention_ja": "水質管理の徹底。飼育密度の低減。水源のPCRまたは培養スクリーニング。飼育容器間の厳格なバイオセキュリティ。コロニー管理用水供給のUV殺菌。",
        "prognosis": "Poor. Meningoencephalitis is often fatal despite treatment. Early systemic infection may respond to appropriate antibiotics. Colony-level outbreaks have high mortality.",
        "prognosis_ja": "予後不良。髄膜脳炎は治療にもかかわらず致死的なことが多い。早期全身感染は適切な抗菌薬に反応しうる。コロニーレベルの集団発生は高い致死率。",
        "onset_pattern": {"acute"},
        "age_predisposition": {"puppy", "young", "adult"},
    },
    {
        "name": "Amphibian Chlamydiosis",
        "name_ja": "両生類クラミジア症",
        "symptoms": {"lethargy", "anorexia", "weight_loss", "skin_lesions", "liver_enlargement", "organ_enlargement", "granulomatous_lesions", "sudden_death"},
        "description": "Systemic infection by Chlamydia spp. in amphibians, causing granulomatous hepatitis, splenomegaly, and chronic wasting. Treatable with doxycycline.",
        "description_ja": "両生類におけるChlamydia属の全身感染症。肉芽腫性肝炎、脾腫大、慢性消耗を引き起こす。ドキシサイクリンで治療可能。",
        "urgency": "high",
        "recommended_tests": ["PCR検査", "組織病理（肝・脾生検）", "血液検査", "Giemsa染色"],
        "causes": "Infection by Chlamydia spp. (obligate intracellular bacteria). Route of infection likely through mucous membranes or skin. Debilitated or crowded amphibians are most susceptible.",
        "causes_ja": "Chlamydia属（偏性細胞内細菌）の感染。粘膜または皮膚を介した感染と推定。衰弱または過密飼育下の両生類が最も感受性が高い。",
        "pathophysiology": "Chlamydial elementary bodies infect host cells, replicate intracellularly as reticulate bodies, and cause granulomatous inflammation in liver, spleen, and other organs. Chronic infection leads to organ fibrosis and functional impairment.",
        "pathophysiology_ja": "クラミジアの基本小体が宿主細胞に感染し、細胞内で網様体として増殖し、肝臓・脾臓等の臓器に肉芽腫性炎症を引き起こす。慢性感染は臓器線維化と機能障害に至る。",
        "treatment": "Doxycycline (5-10 mg/kg PO q24h for 10-14 days) or oxytetracycline (50 mg/kg PO q24h for 10-14 days). Alternatively, tetracycline bath for small species. Supportive care with nutritional support.",
        "treatment_ja": "ドキシサイクリン（5-10 mg/kg PO 1日1回 10-14日間）またはオキシテトラサイクリン（50 mg/kg PO 1日1回 10-14日間）。小型種にはテトラサイクリン浴。栄養サポートを伴う支持療法。",
        "prevention": "Quarantine new arrivals. Reduce overcrowding. Maintain clean environments. Fecal and tissue screening of breeding colonies.",
        "prevention_ja": "新規個体の検疫。過密飼育の低減。清潔な環境の維持。繁殖コロニーの糞便・組織スクリーニング。",
        "prognosis": "Fair with early treatment. Chronic cases with organ fibrosis have guarded prognosis.",
        "prognosis_ja": "早期治療で予後はやや良好。臓器線維化を伴う慢性例では予後は慎重。",
        "onset_pattern": {"subacute", "chronic"},
        "age_predisposition": {"young", "adult", "senior"},
    },

